import{z as A,x as l,o as r,c as p,q as o,j as i,D as B,d as e,s as t,S as s,b as a}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"SCP 与新实证 IO","description":"","frontmatter":{"title":"SCP 与新实证 IO","date":"2026-09-10T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/scp-neio.md","filePath":"econ/scp-neio.md","lastUpdated":1791413859000}'),d={name:"econ/scp-neio.md"};function m(C,E,h,P,c,u){const n=l("Mermaid");return r(),p("div",null,[E[2]||(E[2]=o('<h1 id="scp-与新实证-io" tabindex="-1">SCP 与新实证 IO <a class="header-anchor" href="#scp-与新实证-io" aria-label="Permalink to &quot;SCP 与新实证 IO&quot;">​</a></h1><div class="epigraph"><p>结构—行为—绩效把集中度当成绩效的输入；新实证 IO 先估需求、再解均衡，把「若所有权变了，价格会怎样」写成可计算的反事实。</p><footer>—— Bain 的产业组织传统；Tirole, The Theory of Industrial Organization, 1988；Berry, Levinsohn and Pakes, Automobile Prices in Market Equilibrium, Econometrica 1995</footer></div><p><a href="/econ/minimum-wage-debates">上一课</a>把劳动经济学收在两代最低工资文献：分歧在对照组的构造，不在立场，劳动课程至此收束。本课是<strong>产业组织</strong>领域课的第一课；后课默认已经读完：从市场结构往下走，问的是品种级需求与策略，不是再写三角或原罪。微观主干已有<a href="/econ/monopoly-lerner">垄断与勒纳</a>、<a href="/econ/contestable-markets">可竞争市场</a>，本课不重推 \\(\\mathrm{MR}=\\mathrm{MC}\\)。缺口是：行业表上的 \\(HHI\\) 与「这次合并会不会涨价」之间，缺一条可检验的均衡映射。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>SCP 的减式：\\(P-\\mathrm{MC}\\) 或利润率对集中度、广告、研发回归。句子好听，识别坏：\\(HHI\\) 与成本、需求一起被效率差异决定，高集中可能是低成本厂商胜出，而不是「集中导致加价」。缺口不是再背一次勒纳公式，而是把比较静态换成结构：需求系统给出弹性矩阵，供给给出 Nash 一阶条件，合并改的是所有权，从而改加价，再重解价格。Tirole 提供垄断、寡头、纵向结构的理论地图；BLP 提供可估的差异化需求。本课是这张地图的入口，不把 Cournot 导数再写一遍。</p><h3 id="高-hhi-不是势力的证明" tabindex="-1">高 HHI 不是势力的证明 <a class="header-anchor" href="#高-hhi-不是势力的证明" aria-label="Permalink to &quot;高 HHI 不是势力的证明&quot;">​</a></h3><p>执法里常用集中度阈值当筛子，那是行政方便。经济上，同质品 Cournot 的 \\(HHI\\) 可以进入加价公式，差异化市场里真正进入定价的是交叉弹性，不是企业个数的平方和。两个几乎不相替的品牌合并，份额加总很大，涨价压力仍可很小。反过来，紧密替代的双寡头即使 \\(HHI\\) 中等，加价可以很高。SCP 回归读不到这种矩阵。</p><p><span class="marginnote">SCP 不是「错了所以扔掉」，是减式。相关可以当描述；政策反事实要结构或可信的准实验。NEIO 贵在数据与计算，问的是合并审查真正要的那个导数。</span></p><p><span class="marginnote">术语翻译：HHI 就是把各企业市场份额的平方加起来——两家各占 50% 时是 5000，十家各占 10% 时只有 1000。它量的是「份额有多集中」，但量不出「顾客在品种之间怎么互相流动」，而后者才是涨价压力的真正来源。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>NEIO 三步。(1) 需求：品种份额 \\(s_j(p,\\xi_j)\\)，\\(\\xi_j\\) 为需求侧不可观测，常用特征与成本移动变量作 IV。(2) 供给：在估好的需求下写 Bertrand–Nash 或数量竞争的一阶条件，反推边际成本或行为参数。(3) 反事实：改所有权矩阵，重解均衡价格与福利。与 SCP 对照：SCP 看「集中度高的行业利润高」；NEIO 看「在这组弹性下，去掉一个独立定价者，均衡 \\(p\\) 移动多少」。</p>',11)),(r(),i(s,null,{default:B(()=>[t(n,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20FIN%5B%22%E4%B8%8A%E4%B8%80%E8%AF%BE%3A%20%E6%9C%80%E4%BD%8E%E5%B7%A5%E8%B5%84%E6%96%87%E7%8C%AE%E6%94%B6%E6%9D%9F%22%5D%20--%3E%20IO%5B%22%E6%9C%AC%E8%AF%BE%3A%20%E4%BA%A7%E4%B8%9A%E7%BB%84%E7%BB%87%E7%AC%AC%E4%B8%80%E8%AF%BE%22%5D%0A%20%20SCP%5B%22SCP%3A%20%E9%9B%86%E4%B8%AD%E5%BA%A6%E5%88%B0%E7%BB%A9%E6%95%88%22%5D%20--%3E%20GAP%5B%22%E5%86%85%E7%94%9F%20HHI%2C%20%E6%97%A0%E5%8F%8D%E4%BA%8B%E5%AE%9E%22%5D%0A%20%20GAP%20--%3E%20NEIO%5B%22%E4%BC%B0%E9%9C%80%E6%B1%82%2C%20%E8%A7%A3%E5%9D%87%E8%A1%A1%22%5D%0A%20%20NEIO%20--%3E%20CF%5B%22%E6%89%80%E6%9C%89%E6%9D%83%E5%8F%98%E5%8C%96%E4%B8%8B%E7%9A%84%E4%BB%B7%E6%A0%BC%22%5D%0A%20%20CF%20--%3E%20NEXT%5B%22%E4%B8%8B%E4%B8%80%E8%AF%BE%3A%20%E5%B7%AE%E5%BC%82%E5%8C%96%E5%AE%9A%E4%BB%B7%E6%96%B9%E7%A8%8B%22%5D%0A"})]),fallback:B(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("p",null,[e("静态 Nash 省略合谋、进入、动态学习。进入留给"),a("a",{href:"/econ/entry-exit-sunk"},"进入、退出与沉没成本"),e("；本课只要求：没有需求系统，合并模拟无处落脚。")],-1)),E[4]||(E[4]=a("h2",{id:"机制",tabindex:"-1"},[e("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[5]||(E[5]=a("p",null,"差异化下，每个品种有一群更近的替代。合并把两系交叉弹性从「对手」改成「内部」，多产品厂商会把外部损失内部化，倾向于涨价——幅度由弹性矩阵决定，不由 \\(HHI\\) 数字决定。同质 Cournot 更干净，也更不现实。NEIO 把 IO 从行业平均表接到品种级对象，这是后课每一课的共同语法。",-1)),E[6]||(E[6]=a("p",null,"与微观勒纳的分工：单产品垄断 \\(L=1/|\\varepsilon|\\)；多产品多厂商要把整块 \\(\\Omega\\) 放进加价向量。本课点出这块矩阵存在，下一课才写定价方程。",-1)),(r(),i(s,null,{default:B(()=>[t(n,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20PA%5B%22%E5%93%81%E7%89%8C%20A%20%E6%83%B3%E6%B6%A8%E4%BB%B7%22%5D%20--%3E%20LOSE%5B%22%E5%A4%B1%E5%8E%BB%E9%83%A8%E5%88%86%E9%A1%BE%E5%AE%A2%E5%88%B0%E5%93%81%E7%89%8C%20B%22%5D%0A%20%20LOSE%20--%3E%20SEP%5B%22%E5%90%88%E5%B9%B6%E5%89%8D%EF%BC%9AB%20%E7%9A%84%E6%94%B6%E7%9B%8A%E6%98%AF%E5%88%AB%E4%BA%BA%E7%9A%84%2C%20%E7%AE%97%E7%BA%AF%E6%8D%9F%E5%A4%B1%22%5D%0A%20%20SEP%20--%3E%20STOP%5B%22%E6%B6%A8%E4%BB%B7%E5%8A%A8%E6%9C%BA%E8%A2%AB%E5%8E%8B%E4%BD%8E%22%5D%0A%20%20PA%20--%3E%20OWN%5B%22%E5%90%88%E5%B9%B6%E5%90%8E%EF%BC%9A%E5%93%81%E7%89%8C%20B%20%E5%90%8C%E5%B1%9E%E4%B8%80%E5%AE%B6%22%5D%0A%20%20OWN%20--%3E%20NET%5B%22%E9%A1%BE%E5%AE%A2%E6%B5%81%E5%A4%B1%E5%8F%98%E6%88%90%E5%B7%A6%E6%89%8B%E6%8D%A2%E5%8F%B3%E6%89%8B%22%5D%0A%20%20NET%20--%3E%20UP%5B%22%E6%B6%A8%E4%BB%B7%E5%87%80%E6%8D%9F%E5%A4%B1%E5%8F%98%E5%B0%8F%2C%20%E5%9D%87%E8%A1%A1%E4%BB%B7%E6%A0%BC%E4%B8%8A%E7%A7%BB%22%5D%0A"})]),fallback:B(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[7]||(E[7]=o('<p><span class="marginnote">数字实例：单产品垄断 \\(L=1/|\\varepsilon|\\)：需求弹性为 5 时加价率只有 20%，弹性为 2 时加价率高达 50%。同样的市场份额、不同的弹性，价格结论可以差一倍以上——这就是为什么合并审查要先估需求，而不是先看份额表。</span></p><p><span class="marginnote">Berry–Levinsohn–Pakes 1995 用随机系数把替代模式从「对数线性弹性常数」里解放出来。后课会用到它的逻辑，不必在此估计积分。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>结构需求要有效的成本或特征 IV；弱 IV 时反事实价格不可信，与计量栏弱工具是同一病。本课不写反垄断法条、相关市场定义的法律测试，也不把量化栏并购套利的公告窗搬进来。不要进限价簿。后课默认已经接受：描述性 SCP 与结构性反事实是两句话；产业组织主干从需求矩阵往下，而不是从 \\(HHI\\) 回归往下。</p><p><span class="marginnote">常见误区：初学者容易把「高集中度 → 高利润」读成「拆分大企业就能降价」。若高集中来自低成本赢家胜出，拆分反而抬高成本；若来自紧密替代，涨价压力早就写在弹性矩阵里，\\(HHI\\) 数字本身给不出答案。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>本课是产业组织第一课；后课默认结构反事实，而不是 SCP 回归。</li><li>SCP 把集中度当输入，内生于效率与需求。</li><li>NEIO：估需求、解均衡、改所有权再解一次。</li><li>\\(HHI\\) 不是差异化市场里的势力充分统计。</li><li>出处：Bain；Tirole, <em>The Theory of Industrial Organization</em>；Berry, Levinsohn and Pakes, <em>Econometrica</em> 1995。</li></ul>',7))])}const f=A(d,[["render",m]]);export{D as __pageData,f as default};
